#include <iostream>
#include <vector>
#include <string>
#include <sstream>
#include <stack>

using namespace std;

/**
 * Problem: 2008-37 - Prefix expression evaluation
 * 
 * 解題思路：
 * 1. 前序表達式 (Prefix Expression) 的求值可以從右往左掃描。
 * 2. 如果遇到數字，壓入棧。
 * 3. 如果遇到運算子，從棧中彈出兩個操作數，運算後將結果壓回棧。
 * 4. 注意判斷「非法」情況：操作數不足、最後棧中多於一個元素等。
 */

bool isOp(string s) {
    return s == "+" || s == "-" || s == "*" || s == "/" || s == "%";
}

int main() {
    string line;
    while (getline(cin, line) && line != ".") {
        stringstream ss(line);
        string token;
        vector<string> tokens;
        while (ss >> token) tokens.push_back(token);

        stack<long long> s;
        bool illegal = false;
        for (int i = tokens.size() - 1; i >= 0; --i) {
            if (!isOp(tokens[i])) {
                try {
                    s.push(stoll(tokens[i]));
                } catch (...) { illegal = true; break; }
            } else {
                if (s.size() < 2) { illegal = true; break; }
                long long a = s.top(); s.pop();
                long long b = s.top(); s.pop();
                if (tokens[i] == "+") s.push(a + b);
                else if (tokens[i] == "-") s.push(a - b);
                else if (tokens[i] == "*") s.push(a * b);
                else if (tokens[i] == "/") { if (b == 0) { illegal = true; break; } s.push(a / b); }
                else if (tokens[i] == "%") { if (b == 0) { illegal = true; break; } s.push(a % b); }
            }
        }

        if (illegal || s.size() != 1) cout << "illegal" << endl;
        else cout << s.top() << endl;
    }
    return 0;
}
